let SITE="";try{if(location.hostname.endsWith("github.io"))SITE=location.hostname+location.pathname.replace(/index\.html$/,"").replace(/\/$/,"")}catch(e){}
const OWNER_PIN="change-me";
const CONTACT_EMAIL="your-email@example.com";
const app=document.getElementById("app");
const rnd=a=>a[Math.floor(Math.random()*a.length)];
const peso=n=>"₱"+n.toLocaleString("en-PH");
const esc=v=>String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
function loadOrder(){try{const x=JSON.parse(localStorage.getItem("dateCompassOrder")||"null");if(x)S.order={...S.order,...x}}catch(e){}}
function saveOrderLocal(){try{localStorage.setItem("dateCompassOrder",JSON.stringify(S.order))}catch(e){}}
loadOrder();
const ok=(x,f)=>(f.p=="a"||x.p==f.p||x.p=="a")&&(f.t=="a"||!x.t||x.t==f.t||(f.t=="l"&&x.t=="n"))&&(f.s=="a"||x.s==f.s)&&(f.cat=="a"||!x.cat||x.cat==f.cat)&&(f.car!="n"||!x.r);
function opts(L,f,cap){
 for(const g of [f,{...f,s:"a"},{...f,s:"a",t:"a"}]){const r=L.filter(x=>ok(x,g)&&x.c<=cap);if(r.length)return r}
 return [];
}
const aPool=()=>{const r=opts(A,S,Math.max(S.b-150,0));if(S.car=="y"){const car=r.filter(x=>x.r);if(car.length)return car}return r.length?r:opts(A,S,S.b)};
const fPool=()=>{const base=S.act&&S.act.t=="n"?F.filter(x=>x.k):F.filter(x=>!x.k||x.k==2);const mode=S.foodMode=="a"?base:base.filter(x=>x.m==S.foodMode);return opts(mode,{p:S.p,t:"a",s:S.s},S.act?Math.max(S.b-S.act.c,150):S.b)};
const total=()=>(S.act?S.act.c:0)+(S.food?S.food.c:0);
const CH={p:{c:"Inside CDO",m:"Outside CDO",a:"Anywhere"},car:{a:"Either",y:"I have a car",n:"No car"},b:{300:"₱300",800:"₱800",1500:"₱1,500",5000:"Splurge"},t:{a:"Any length",s:"2 hours",l:"Half day or more",n:"Overnight"},s:{a:"Either",i:"Indoor",o:"Outdoor"},cat:{a:"All categories",...CAT},foodMode:{a:"Any food style",out:"Eat out",home:"Cook at home",breakfast:"Breakfast",cafe:"Cafe & dessert",street:"Street & market",takeout:"Takeout & picnic",healthy:"Lighter & healthy",special:"Special food date"}};
function sel(label,key){return `<label class="selectfield"><span>${label}</span><select aria-label="${label}" onchange="setf('${key}',this.value)">${Object.entries(CH[key]).map(([v,t])=>`<option value="${v}"${String(S[key])==v?" selected":""}>${t}</option>`).join("")}</select></label>`}
function filters(){
 const cu=S.view=="custom";
 return `<a class="back" href="#home">Back</a>
 <div class="steps"><span class="on">1 Choose</span><span${cu||S.gen?' class="on"':""}>2 Your plan</span><span>3 Kit</span></div>
 <h2>${cu?"Build your own date":"Surprise us"}</h2>
 <p class="mute">${cu?"Set the basics, then pick each part yourself.":"Tell us the basics and we choose the rest."}</p>
 ${sel("Where","p")}${sel("Do you have a car?","car")}${sel("Category","cat")}${sel("Food style","foodMode")}<label class="selectfield"><span>Budget for two</span><input class="budgetinput" type="number" min="0" step="50" inputmode="numeric" value="${S.b||""}" placeholder="e.g. 800" aria-label="Budget for two" oninput="setBudget(this.value)"><small>Enter your actual total budget for both of you.</small></label>${sel("How long","t")}${sel("Setting","s")}`
 +(cu?"":`<button class="go" onclick="gen()" ${S.b>0?"":"disabled"}>Plan my date</button>`);
}
function foodGuide(x){
 const z=(x.n+" "+(x.d||"")).toLowerCase();
 if(/jollibee|mcdo|chowking|greenwich|mang inasal|kfc|shakey|bonchon|starbucks|coffee bean/.test(z))return {what:"This date is simply about going to the chosen restaurant or cafe together. The food is the setting for the date, so you can focus on talking, laughing, and enjoying the meal.",steps:["Choose a convenient branch and check its current hours and menu.","Go together and order within your budget.","Put the phones away for part of the meal and talk.","After eating, add a short walk, dessert, or another small activity if you want."],need:"Your budget and a way to get there.",tip:"Menu items, prices, and branch hours can change, so check before going."};
 return null;
}
function guideFor(x){
 const z=(x.n+" "+(x.d||"")).toLowerCase();
 if(/vision board/.test(z))return {what:"You and your partner make a collage of things you want to experience, achieve, or build together. It is a fun way to talk about your future while making something you can keep.",steps:["Pick a comfortable spot and arrive early if you want the sunset part.","Talk about shared dreams such as travel, home, money, family, hobbies, or experiences.","Choose pictures, words, drawings, or notes that represent those dreams and arrange them on paper or a board.","Finish it together, give it a title, and take a photo to keep the memory."],need:"Paper or cardboard, old magazines or printed pictures, scissors, glue or tape, and pens or markers. A digital board works too.",tip:"The goal is the conversation, not making a perfect-looking board."};
 if(/scavenger hunt/.test(z))return {what:"A playful hunt where you and your partner follow clues or challenges and try to complete them together.",steps:["Choose a safe area you both know.","Take turns picking a clue or challenge.","Take photos or proof when you complete each one.","Finish with a snack, drink, or small prize for the winner."],need:"Your phone, the clue list, and comfortable shoes.",tip:"Keep it to about 5–10 challenges so it stays fun."};
 if(/blind.?fold|blind taste|taste test/.test(z))return {what:"One partner tastes or identifies food or drinks without seeing them, then you switch. The fun comes from guessing and laughing at the answers.",steps:["Prepare a few safe samples and check allergies first.","Keep each sample hidden from the person guessing.","Let them taste or smell one and guess it.","Switch roles and compare your scores."],need:"Small food or drink samples, cups or plates, and water.",tip:"Use familiar foods and avoid anything that could cause an allergy."};
 if(/time capsule/.test(z))return {what:"You create a small box or envelope of notes, photos, predictions, and memories to open together in the future.",steps:["Choose a future opening date.","Each person writes a note about your relationship and hopes for that date.","Add photos or small memories.","Seal it, write the opening date on it, and store it safely."],need:"A box or envelope, paper, pens, and optional photos.",tip:"Put the opening date in your calendar."};
 if(/bucket.?list|dream vacation|future goals|couple goals/.test(z))return {what:"You make a shared list of things you want to do, see, learn, or accomplish together.",steps:["Each person writes several ideas.","Share them and circle the ideas you both want.","Choose one easy goal you can actually start soon.","Add a next step or date beside it."],need:"Paper or a shared notes app.",tip:"Mix big dreams with small goals you can actually check off."};
 if(/progressive dinner|food crawl|restaurant crawl|coffee crawl|dessert crawl/.test(z))return {what:"Instead of doing the whole meal in one place, you visit different spots for different parts of the date.",steps:["Choose two or three nearby stops.","Decide what you will have at each stop.","Keep portions and spending small enough for the next stop.","Finish at your favorite place and compare the stops."],need:"Transportation, a simple route, and your budget.",tip:"Pick nearby places so travel does not take over the date."};
 const guides={food:["This is a food-focused date. The food experience is the main activity while you spend time together.","Choose the food experience.","Go together and put the phones away for a while.","Share something and talk while you eat.","Finish with a walk, dessert, or another small activity."],home:["This is an at-home date. You stay in and turn an ordinary evening into a planned activity.","Prepare the space and gather what you need.","Set aside uninterrupted time.","Do the activity together instead of separately.","Finish by talking about your favorite part."],creative:["This is a make-something-together date. You create, draw, write, craft, or build something side by side.","Choose the project.","Gather the materials and work together.","Help each other when something goes wrong.","Keep the finished result as a memory."],games:["This is a playful date built around a game or friendly challenge.","Choose the game and agree on the rules.","Play a few rounds and keep competition light.","Give the winner a silly prize or let the loser choose dessert.","Take a break between rounds to talk."],nature:["This is an outdoor date where the scenery and time together are the main activity.","Choose a safe place and check the weather.","Bring water and location-specific essentials.","Walk, sit, explore, or enjoy the view.","End with food, coffee, photos, or conversation."],car:["This is a car-based date where the drive is part of the experience.","Pick a route and destination or stops.","Prepare a playlist and snacks if you want.","Drive safely and take breaks when needed.","Finish with food, photos, or a short activity."],adventure:["This is an activity-focused date where you try something more active or unfamiliar together.","Check the activity rules, schedule, cost, and difficulty.","Wear the right clothes and bring what is required.","Do it at a pace that works for both of you.","Relax together afterward."],conversation:["This is a conversation-focused date. The activity or setting makes it easier to talk about memories, feelings, or the future.","Find a comfortable place without distractions.","Take turns answering the prompts.","Ask follow-up questions and listen.","End with one thing you appreciate about each other."],learning:["This is a learn-something-together date. You explore a topic, place, class, book, or skill.","Choose the topic or place together.","Learn side by side.","Compare what each of you found interesting.","Choose one thing you would like to learn next."],fitness:["This is an active date built around moving together.","Pick an activity that suits both fitness levels.","Warm up and bring water.","Keep the pace comfortable.","Cool down and reward yourselves afterward."],kindness:["This is a date where you do something thoughtful for another person, an animal, or your community.","Choose a realistic act of kindness.","Prepare what you need.","Do it together without expecting anything back.","Talk afterward about how it felt."],night:["This is an evening or nighttime date built around atmosphere, food, a view, a game, or simply being together.","Choose a safe place and check its hours or conditions.","Bring what you need for the weather and lighting.","Do the planned activity together.","Finish with a snack, drink, or conversation."],romantic:["This is a simple romantic date built around giving each other focused time.","Choose the place and set aside uninterrupted time.","Add one small personal touch such as a note or favorite snack.","Do the activity together and stay present.","End by telling each other one thing you enjoyed."]};
 const g=guides[x.cat]||guides.romantic;
 return {what:g[0],steps:g.slice(1),need:"Whatever the activity requires, plus a little time and attention.",tip:"Check current prices, opening hours, weather, rules, and availability before going when relevant."};
}
function guideHtml(x){
 if(!x)return "";
 const g=foodGuide(x)||guideFor(x);
 return '<details class="dateguide"><summary>What is this date? · How do we do it?</summary><p><b>What it is:</b> '+esc(g.what)+'</p><p><b>How to do it:</b></p><ol>'+g.steps.map(s=>'<li>'+esc(s)+'</li>').join("")+'</ol><p><b>What you need:</b> '+esc(g.need)+'</p><p><b>Tip:</b> '+esc(g.tip)+'</p></details>';
}
function slot(label,key,pool,item){
 const cu=S.view=="custom",L=key=="act"?A:F;
 return `<div class="card"><div class="lab">${label}</div>`
 +(cu?`<select aria-label="${label}" onchange="pick('${key}',this.value)"><option value="">Choose one (${pool.length} matches)</option>${pool.map(x=>`<option value="${L.indexOf(x)}"${item&&item.n==x.n?" selected":""}>${x.n}, about ${peso(x.c)}</option>`).join("")}</select>`:"")
 +(item?`<h3>${esc(item.n)}</h3><p>${esc(item.d)}</p><p class="tag">About ${peso(item.c)} for two. ${PL[item.p]}. ${CAT[item.cat]?" · "+CAT[item.cat]:""}</p>${guideHtml(item)}`:"")
 +`<button class="ghost" onclick="shuffle('${key}')">${cu?"Surprise me":"Try another"}</button></div>`;
}
function plan(){
 const ap=aPool();
 if(!ap.length)return `<div class="card"><p>Nothing fits that combination yet. Try a bigger budget or set the place to Anywhere.</p></div>`;
 const t=total(),bl=S.b>=5000?"your splurge budget":"your "+peso(S.b)+" budget",over=t>S.b?" That is a bit over, so try another pick.":"";
 return `<h2 style="margin-top:22px">Your date</h2>`+slot("Activity","act",ap,S.act)+slot("Food","food",fPool(),S.food)
 +(t?`<div class="total">About ${peso(t)} of ${bl}.${over}</div>`:"")
 +`<p class="note">Food ideas now include eating out, takeout, street food, cafe dates, and actual cook-together meals. Prices are rough planning estimates, so check current menus and ingredient costs before you go.</p>`
 +`<p class="brandline">♥ Date Compass${SITE?" "+SITE:""}</p><div class="bar">`+(S.view=="random"?`<button class="ghost" onclick="gen()">New plan</button>`:"")+`<button class="ghost" onclick="startKit()">Get the Date Compass Kit</button><button class="ghost" id="cp" onclick="copyPlan()">Copy</button></div>`;
}
function about(){
 return '<a class="back" href="#home">Back home</a><section class="panel"><h1>About Date Compass</h1><p>Date Compass helps couples plan a date around their budget, preferred setting, and transport in Cagayan de Oro and Misamis Oriental.</p><p>Choose your preferences to get a suggested activity and food idea, or use Surprise Me for a fresh combination.</p><p class="note">This is an early frontend version. Ideas and costs are estimates, not verified venue listings. Confirm current prices, opening hours, availability, transport, and safety before you go.</p><h3>Digital plan or physical kit?</h3><p>The digital planner helps you choose an idea. The optional physical kit is a separate printed experience. Orders are not submitted automatically; you must send the prepared order message to the Date Compass owner.</p></section>';
}
function contact(){
 return '<a class="back" href="#home">Back home</a><section class="panel"><h1>Contact Date Compass</h1><p>The kit order screen can prepare an email, but the contact email is not configured yet.</p><p class="note">For now, avoid entering sensitive information. Kit details stay in this browser until you choose to copy or email them. There is no online order database connected yet.</p><a class="cta" href="#custom">Plan a date</a></section>';
}
function home(){
 const ic={a:'<circle cx="12" cy="12" r="9"/><path d="M15.5 8.5l-2 5-5 2 2-5z"/>',b:'<path d="M3 7h18v3a2 2 0 0 0 0 4v3H3v-3a2 2 0 0 0 0-4z"/>',c:'<path d="M12 20s-7-4.4-7-10a4 4 0 0 1 7-2.5A4 4 0 0 1 19 10c0 5.6-7 10-7 10z"/>'};
 const cir=(k,c,t,d)=>`<div class="cir ${c}"><div><svg viewBox="0 0 24 24">${ic[k]}</svg><b>${t}</b><span>${d}</span></div></div>`;
 return `<div class="hero2"><i class="c1"></i><i class="c2"></i><i class="c3"></i>
 <div class="txt"><h1>Find your best date spot</h1>
 <p class="lead2">Pick a place, budget, and whether you have a car in Cagayan de Oro and Misamis Oriental. Get a full date plan. Order the physical kit when you want the printed experience.</p>
 <a class="cta" href="#custom">Create your date spot</a><a class="cta cta2" href="#random">Surprise me</a></div>
 <div class="phones"><div class="ph p1"><div class="pn"></div><div class="pl">Your date</div><div class="pt"><small>Activity</small><b>Sunset walk at Gaston Park</b></div><div class="pt"><small>Food</small><b>Street food crawl</b></div><div class="pc">Your date plan</div></div><div class="ph p2"><div class="pn"></div><div class="pl">Your Date Compass Kit</div><div class="pt"><small>Made for two</small><b>A date planned around you</b></div><div class="pq">Your next date, made special.</div><div class="pt"><small>Inside the kit</small><b>10 printed question cards</b></div><div class="pc">Made for your date</div></div></div></div>
 <section class="hiw"><div class="hiwt"><h2>How it works</h2><p class="mute">Choose your basics, get a full plan, then order the physical kit if you want the full date experience. No more running out of ideas.</p></div>
 <div class="circles">${cir("a","ca","Pick the basics","Place and budget")}${cir("b","cb","Get your plan","Activity and food")}${cir("c","cc","Get the kit","Personalized for you")}</div></section>
 <section class="quick"><h2>Start with a vibe</h2><p class="mute">Skip the setup and jump straight to the kind of date you want.</p><div class="quickgrid"><button class="quickcat" onclick="quickCat('romantic')"><b>Romantic</b><span>Sweet & romantic</span></button><button class="quickcat" onclick="quickCat('food')"><b>Food</b><span>Eat & explore</span></button><button class="quickcat" onclick="quickCat('adventure')"><b>Adventure</b><span>Try something new</span></button><button class="quickcat" onclick="quickCat('home')"><b>At Home</b><span>Cozy at home</span></button><button class="quickcat" onclick="quickCat('car')"><b>Car Date</b><span>Hit the road</span></button><button class="quickcat" onclick="quickCat('conversation')"><b>Deep Conversation</b><span>Talk & connect</span></button><button class="quickcat" onclick="quickCat('creative')"><b>Creative</b><span>Make something</span></button><button class="quickcat" onclick="quickCat('games')"><b>Games</b><span>Play together</span></button><button class="quickcat" onclick="quickCat('nature')"><b>Nature</b><span>Fresh air</span></button><button class="quickcat" onclick="quickCat('free')"><b>Free / Low Cost</b><span>Keep it simple</span></button></div></section><p class="note">1,000 wholesome date ideas, including car-friendly options. All ideas are placeholders that still need checking.</p>`;
}
function qview(){
 const i=S.qi,n=S.q.length;
 if(i>=n)return `<div class="q">That was the last one. Hope the date goes well.</div><a class="back" href="#${S.from}">Back to your plan</a>`;
 return `<a class="back" href="#${S.from}">Back to your plan</a><div class="q"><div class="cnt">Question ${i+1} of ${n}</div>${S.q[i]}<div class="brand">Date Compass${SITE?" "+SITE:""}</div></div>
 <button class="ghost" onclick="qn(-1)"${i?"":" disabled"}>Previous</button><button onclick="qn(1)">${i==n-1?"Finish":"Next question"}</button>`;
}
const newCode=()=>"DC-"+Math.random().toString(36).slice(2,6).toUpperCase();
function toggleSurp(){S.surp=!S.surp;render()}

function startKit(){S.from=S.view;if(!S.code)S.code=newCode();S.orderSaved=false;go("kit")}
function readOrderForm(){const g=id=>document.getElementById(id);if(!g("oname"))return;S.order.name=g("oname").value.trim();S.order.partner=g("opartner").value.trim();S.order.occasion=g("ooccasion").value.trim();S.order.date=g("odate").value;S.order.contact=g("ocontact").value.trim();S.order.messenger=g("omessenger").value.trim();S.order.address=g("oaddress")?g("oaddress").value.trim():"";S.order.note=g("onote").value.trim()}
function setDelivery(v){readOrderForm();S.order.delivery=v;render()}
function orderText(){const o=S.order;return "DATE COMPASS KIT ORDER\nOrder code: "+S.code+"\nActivity: "+(S.act?S.act.n:"To be decided")+"\nFood: "+(S.food?S.food.n:"To be decided")+"\nCategory: "+(S.act&&S.act.cat?CAT[S.act.cat]:"Not specified")+"\nSurprise version: "+(S.surp?"Yes":"No")+"\n\nCUSTOMER\nName: "+o.name+"\nPartner name: "+o.partner+"\nOccasion: "+(o.occasion||"Not specified")+"\nKit needed by: "+(o.date||"Not specified")+"\nMobile: "+o.contact+"\nMessenger: "+(o.messenger||"Not provided")+"\n\nFULFILLMENT\nMethod: "+(o.delivery=="delivery"?"Delivery":"Pick up")+"\n"+(o.delivery=="delivery"?"Address: "+(o.address||"Not provided")+"\n":"")+"\nPERSONALIZATION / NOTES\n"+(o.note||"None")+"\n\nEstimated plan total: "+peso(total())+"\nPlease confirm final price, availability, pickup/delivery details, and any partner voucher before production."}
function saveAndOrder(){readOrderForm();const er=document.getElementById("oerr");if(!S.order.name||!S.order.partner||!S.order.contact||!S.order.date){er.textContent="Please add your name, your partner name, mobile number, and the date you need the kit.";return}if(S.order.delivery=="delivery"&&!S.order.address){er.textContent="Please add the delivery address or choose Pick up.";return}saveOrderLocal();S.orderSaved=true;render()}
async function copyOrder(){const b=document.getElementById("copyorder");try{await navigator.clipboard.writeText(orderText());b.textContent="Copied! Paste it in Messenger"}catch(e){b.textContent="Copy failed. Select the order text below."}}
function emailOrder(){location.href="mailto:"+CONTACT_EMAIL+"?subject="+encodeURIComponent("Date Compass kit order "+S.code)+"&body="+encodeURIComponent(orderText())}
function clearOrder(){S.order={name:"",partner:"",occasion:"",date:"",delivery:"pickup",address:"",contact:"",messenger:"",note:""};S.orderSaved=false;saveOrderLocal();render()}
function orderForm(){
 const o=S.order;
 let h='<section class="panel orderbox"><div class="steps"><span class="on">1 Your date</span><span class="on">2 Your details</span><span>3 We prepare it</span></div><h3>Make the kit yours</h3><p class="mute">These details are for your order and the printed card. You do not need an account.</p>';
 h+='<div class="formgrid"><label>Your name *<input id="oname" autocomplete="name" value="'+esc(o.name)+'" placeholder="e.g. Jasper"></label><label>Partner name *<input id="opartner" autocomplete="name" value="'+esc(o.partner)+'" placeholder="e.g. Maria"></label><label>Occasion<input id="ooccasion" value="'+esc(o.occasion)+'" placeholder="Date night, anniversary, birthday..."></label><label>Date you need the kit *<input id="odate" type="date" value="'+esc(o.date)+'"></label><label>Mobile number *<input id="ocontact" type="tel" autocomplete="tel" value="'+esc(o.contact)+'" placeholder="09xx xxx xxxx"></label><label>Messenger name/link<input id="omessenger" value="'+esc(o.messenger)+'" placeholder="Optional, for easier follow-up"></label></div>';
 h+='<fieldset><legend>How should we get the kit to you? *</legend><div class="chips"><button type="button" class="chip" aria-pressed="'+(o.delivery=="pickup")+'" onclick="setDelivery(\'pickup\')">Pick up</button><button type="button" class="chip" aria-pressed="'+(o.delivery=="delivery")+'" onclick="setDelivery(\'delivery\')">Delivery</button></div></fieldset>';
 if(o.delivery=="delivery")h+='<label>Delivery address / landmark *<textarea id="oaddress" rows="3" placeholder="House/building, street, barangay, city + nearby landmark">'+esc(o.address)+'</textarea></label>';
 h+='<label>Special note for us<textarea id="onote" rows="3" placeholder="Card message, colors, surprise instructions, anything we should know...">'+esc(o.note)+'</textarea></label><p id="oerr" class="err" role="alert"></p><div class="orderactions"><button onclick="saveAndOrder()">Save details & create order message</button><button class="ghost" onclick="clearOrder()">Clear details</button></div><p class="note">Your details stay in this browser until you choose to copy or email the order.</p></section>';
 return h;
}
function kitview(){
 if(!S.code)S.code=newCode();
 const o=S.order;
 let h='<a class="back" href="#'+S.from+'">Back to your plan</a><h2>Your date kit</h2><p class="mute">We will collect the details once, then you can send us one clean order message. No back-and-forth hunting for names, dates, or delivery info.</p>';
 h+='<div class="kit'+(S.surp?" sealed":"")+'"><div class="kh">Our date</div>'+(S.surp?'<div class="seal">Sealed surprise. Open on the date.</div>':"");
 h+='<div class="kr"><span>For</span><b>'+(esc(o.partner)||"Your partner")+'</b></div><div class="kr"><span>From</span><b>'+(esc(o.name)||"Your name")+'</b></div><div class="kr"><span>Activity</span><b>'+(S.act?S.act.n:"To be decided")+'</b></div><div class="kr"><span>Food</span><b>'+(S.food?S.food.n:"To be decided")+'</b></div>';
 if(o.occasion)h+='<div class="kr"><span>Occasion</span><b>'+esc(o.occasion)+'</b></div>';
 h+='<div class="kitinclude"><b>📦 Included in your Date Compass Kit</b><p>10 printed question cards to use during your date. These questions are not shown in the app. They are included only in the physical kit.</p></div><div class="vou"><span class="tag">Partner voucher</span><b>Show this card at [Partner name]</b><p>[Offer, for example a free drink with any meal]</p><span class="tag">Valid until [date]. One voucher per card.</span><div class="code">Card code: '+S.code+'</div></div><div class="kf">Planned with Date Compass.</div></div>';
 h+='<button class="ghost" onclick="toggleSurp()">'+(S.surp?"Show the plan":"Make it a surprise")+'</button>'+orderForm();
 if(S.orderSaved)h+='<section class="panel success"><h3>Ready to send ✓</h3><p>Your order is organized into one message. Send it through Messenger or email.</p><pre class="ordermsg">'+esc(orderText())+'</pre><div class="orderactions"><button id="copyorder" onclick="copyOrder()">Copy for Messenger</button><button class="ghost" onclick="emailOrder()">Email order</button></div><p class="note">Keep order code <b>'+S.code+'</b> after sending it so we can find the order quickly.</p></section>';
 return h;
}
function cardsview(){
 return '<a class="back" href="#kit">Back to kit card</a><section class="panel" role="status"><h2>Question-card bank not configured</h2><p>The owner printing screen is paused because the question bank is not present in this frontend. Add and review the approved card content before printing customer kits.</p></section>';
}
function render(){app.className=S.view=='home'?'wide':'';
 const cur=(S.view=='q'||S.view=='kit')?S.from:S.view;
 document.querySelectorAll('header.site nav a').forEach(a=>{if(a.getAttribute('href')=='#'+cur)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 const v=S.view;
 app.innerHTML=v=="home"?home():v=="about"?about():v=="contact"?contact():v=="cards"?cardsview():v=="q"?qview():v=="kit"?kitview():filters()+((v=="custom"||S.gen)?plan():"");
}
function quickCat(k){S.cat=k;S.gen=false;S.act=null;S.food=null;go("custom")}
function setBudget(v){
 S.b=Math.max(0,Number(v)||0);
 if(S.view=="random")S.gen=false;
 else{
  if(S.act&&!aPool().includes(S.act))S.act=null;
  if(S.food&&!fPool().includes(S.food))S.food=null;
 }
 const btn=document.querySelector(".go");
 if(btn)btn.disabled=S.b<=0;
}
function setf(k,v){
 if(k=="b"){setBudget(v);return}
 S[k]=v;
 if(S.view=="random")S.gen=false;
 else{ if(S.act&&!aPool().includes(S.act))S.act=null; if(S.food&&!fPool().includes(S.food))S.food=null }
 render();
}
function gen(){
 const ap=aPool();S.act=ap.length?rnd(ap):null;
 const fp=fPool();S.food=fp.length?rnd(fp):null;S.gen=true;render();
}
function pick(k,i){const L=k=="act"?A:F;S[k]=i===""?null:L[+i];render()}
function shuffle(k){
 const pool=k=="act"?aPool():fPool(),cur=S[k],alt=pool.filter(x=>x!=cur);
 const c=alt.length?rnd(alt):cur;
 if(c){S[k]=c;
  if(k=="act"&&S.view=="random"&&S.food&&S.food.c>Math.max(S.b-c.c,150)){const fp=fPool();if(fp.length)S.food=rnd(fp)}}
 render();
}
function startQ(){S.from=S.view;S.q=[...Q].sort(()=>Math.random()-.5).slice(0,10);S.qi=0;go("q")}
function qn(d){S.qi=Math.max(0,S.qi+d);render();scrollTo(0,0)}
async function copyPlan(){
 const t=`Date plan for us
Activity: ${S.act?S.act.n:"to be decided"}
Food: ${S.food?S.food.n:"to be decided"}
Estimated total: about ${peso(total())}
Planned with Date Compass${SITE?" "+SITE:""}`;
 const b=document.getElementById("cp");
 try{await navigator.clipboard.writeText(t);b.textContent="Copied"}catch(e){b.textContent="Could not copy, try a screenshot"}
}
const RM=matchMedia("(prefers-reduced-motion:reduce)").matches;
let IO=null;
function reveal(){
 if(RM||!("IntersectionObserver" in window))return;
 if(IO)IO.disconnect();
 IO=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){const t=e.target;t.classList.add("in");IO.unobserve(t);setTimeout(()=>{t.classList.add("done");t.style.transitionDelay=""},1000)}}),{threshold:.12,rootMargin:"0px 0px -6% 0px"});
 document.querySelectorAll("#app .hiw,#app .cir,#app .panel,#app details,#app .card,#app .total,#app .big").forEach((el,i)=>{el.classList.add("rv");el.style.transitionDelay=(i%4)*70+"ms";IO.observe(el)});
}
addEventListener("scroll",()=>{const h=document.querySelector("header.site");if(h)h.classList.toggle("sc",scrollY>8)},{passive:true});
function go(h){try{history.pushState(null,"","#"+h)}catch(e){}route(h)}
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest('a[href^="#"]');if(!a||e.metaKey||e.ctrlKey)return;e.preventDefault();go(a.getAttribute("href").slice(1)||"home")});
addEventListener("popstate",()=>route());
function route(hh){
 const h=hh||location.hash.slice(1)||"home";
 if((h=="custom"||h=="random")&&S.view=="home"){S.act=S.food=null;S.gen=false}
 if(h=="owner"){const pin=prompt("Owner PIN");if(pin===OWNER_PIN){S.owner=true;document.body.classList.add("owner")}go("home");return}
 if(h=="cards"&&!S.owner){go("home");return}
 if(h=="q"&&!S.q.length){go("home");return}
 if(h=="kit"&&!S.act&&!S.food){go("home");return}
 S.view=h;render();scrollTo(0,0);
 app.classList.remove('enter');void app.offsetWidth;app.classList.add('enter');reveal();
}
addEventListener("hashchange",route);
document.getElementById("yr").textContent=new Date().getFullYear();
route();